//! Public authoritative World action/tick checks at the recorded implementation.
use gielinor_world::{simulation::{World,PlayerData,ActorId,Action,WorldEvent},prayer::{Config,Event},prayer_preservation::Rule,inventory::Item,stats::Stats,npc::RandomSource,CoordGrid};
struct Draw{n:u32,calls:usize}impl RandomSource for Draw{fn below(&mut self,n:u32)->u32{assert_eq!(n,80);self.calls+=1;self.n}}
fn setup(worn:bool,confirm:bool)->(World,ActorId){let mut w=World::default();w.collision.allocate(3216,3216,0);w.prayer=Some(Config{skill:5,animation:827,bones:[(526,4.5)].into(),necklace:None,restore:Default::default(),worn_xp_percent:Default::default(),chaos:if confirm{Some([3220,3220,3220,3220])}else{None}});w.prayer_preservation=Some(Rule{pieces:[(25438,0),(25434,4),(25436,7),(25440,10)],excluded:[25766,25769,25772,25775,25778].into()});let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);let mut p=PlayerData::new(1,"World burial observer".into(),CoordGrid::new(3220,3220,0).unwrap(),stats);p.xp_rate_hundreds=125;for s in 0..28{p.inventory.restore_slot(s,Some(Item{id:526,count:1,vars:0})).unwrap();}if worn{p.equipment.restore_slot(0,Some(Item{id:25438,count:1,vars:0})).unwrap();}w.queue_login(1,p).unwrap();w.tick_with_random(&mut Draw{n:0,calls:0}).unwrap();let a=w.actors().next().unwrap();w.set_membership(a,true).unwrap();w.drain_events();(w,a)}
fn tick(w:&mut World,r:&mut Draw){w.tick_with_random(r).unwrap();}
#[test]fn admission_completion_live_robes_member_and_duplicate_controls(){let mut cases=0;for selected in [7,27]{for mode in 0..7{let(mut w,a)=setup(mode!=1,false);let mut rng=Draw{n:79,calls:0};let initial=w.data(a).unwrap().clone();w.submit(a,Action::BuryItemSlot{slot:selected,item:526}).unwrap();tick(&mut w,&mut rng);assert_eq!(w.data(a).unwrap().inventory,initial.inventory);assert_eq!(w.data(a).unwrap().stats,initial.stats);assert_eq!(rng.calls,0);assert!(w.drain_events().iter().any(|e|matches!(e,WorldEvent::Prayer{event:Event::Animation(827),..})));
match mode{0=>{},1=>{w.data_mut(a).unwrap().equipment.restore_slot(0,Some(Item{id:25438,count:1,vars:0})).unwrap();},2=>{w.data_mut(a).unwrap().equipment.restore_slot(0,None).unwrap();},3=>{w.set_membership(a,false).unwrap();},4=>{w.data_mut(a).unwrap().equipment.restore_slot(0,Some(Item{id:25438,count:2,vars:0})).unwrap();},5=>{w.data_mut(a).unwrap().inventory.restore_slot(selected,None).unwrap();},6=>{w.data_mut(a).unwrap().inventory.restore_slot(selected,Some(Item{id:532,count:1,vars:0})).unwrap();},_=>{w.data_mut(a).unwrap().stats.set_current(3,0);}}
let before=w.data(a).unwrap().clone();for _ in 0..3{tick(&mut w,&mut rng);}let next=w.data(a).unwrap();let complete=mode<5;let save=mode<2;let mut inv=before.inventory.clone();if complete&&!save{inv.restore_slot(selected,None).unwrap();}assert_eq!(next.inventory,inv,"mode{mode} slot{selected}");let mut stats=before.stats.clone();if complete{stats.set_fine_xp(5,56).unwrap();}assert_eq!(next.stats,stats,"mode{mode} slot{selected}");assert_eq!(rng.calls,usize::from(save),"mode{mode}");assert_eq!(next.equipment,before.equipment);let final_image=next.clone();for _ in 0..3{tick(&mut w,&mut rng);}assert_eq!(w.data(a).unwrap().inventory,final_image.inventory);assert_eq!(w.data(a).unwrap().stats,final_image.stats);cases+=1;
}}println!("PG_ZEALOT_WORLD {cases} selected admission noinitialXP/liveequip/remove/member/malformed/stalebone/zeroHP completion and noReplay PASS");}
